<?php
class ModelExtensionProbgServicesService extends Model {
    public function addService($data){$this->db->query("INSERT INTO ".DB_PREFIX."probg_service SET category_id='".(int)$data['category_id']."', image='".$this->db->escape($data['image'])."', social_image='".$this->db->escape($data['social_image'])."', price='".(float)$data['price']."', show_price='".(int)$data['show_price']."', enquiry_status='".(int)$data['enquiry_status']."', sort_order='".(int)$data['sort_order']."', status='".(int)$data['status']."', date_available=".(!empty($data['date_available'])?"'".$this->db->escape($data['date_available'])."'":"NULL").", date_added=NOW(), date_modified=NOW()");$id=$this->db->getLastId();$this->saveDescriptions($id,$data);$this->saveStores($id,$data);$this->saveImages($id,$data);$this->saveRelated($id,$data);$this->saveProducts($id,$data);$this->saveSeoUrls($id,$data);$this->cache->delete('probg_services');return $id;}
    public function editService($id,$data){$this->db->query("UPDATE ".DB_PREFIX."probg_service SET category_id='".(int)$data['category_id']."', image='".$this->db->escape($data['image'])."', social_image='".$this->db->escape($data['social_image'])."', price='".(float)$data['price']."', show_price='".(int)$data['show_price']."', enquiry_status='".(int)$data['enquiry_status']."', sort_order='".(int)$data['sort_order']."', status='".(int)$data['status']."', date_available=".(!empty($data['date_available'])?"'".$this->db->escape($data['date_available'])."'":"NULL").", date_modified=NOW() WHERE service_id='".(int)$id."'");foreach(array('probg_service_description','probg_service_to_store','probg_service_image','probg_service_related','probg_service_product') as $t)$this->db->query("DELETE FROM ".DB_PREFIX.$t." WHERE service_id='".(int)$id."'");$this->deleteSeoUrls($id);$this->saveDescriptions($id,$data);$this->saveStores($id,$data);$this->saveImages($id,$data);$this->saveRelated($id,$data);$this->saveProducts($id,$data);$this->saveSeoUrls($id,$data);$this->cache->delete('probg_services');}
    public function deleteService($id){foreach(array('probg_service','probg_service_description','probg_service_to_store','probg_service_image','probg_service_related','probg_service_product') as $t)$this->db->query("DELETE FROM ".DB_PREFIX.$t." WHERE service_id='".(int)$id."'");$this->db->query("DELETE FROM ".DB_PREFIX."probg_service_related WHERE related_id='".(int)$id."'");$this->deleteSeoUrls($id);$this->cache->delete('probg_services');}
    public function getService($id){return $this->db->query("SELECT s.*,sd.name FROM ".DB_PREFIX."probg_service s LEFT JOIN ".DB_PREFIX."probg_service_description sd ON(s.service_id=sd.service_id AND sd.language_id='".(int)$this->config->get('config_language_id')."') WHERE s.service_id='".(int)$id."'")->row;}
    public function getServices($data=array()){$sql="SELECT s.*,sd.name,cd.name AS category_name FROM ".DB_PREFIX."probg_service s LEFT JOIN ".DB_PREFIX."probg_service_description sd ON(s.service_id=sd.service_id AND sd.language_id='".(int)$this->config->get('config_language_id')."') LEFT JOIN ".DB_PREFIX."probg_service_category_description cd ON(s.category_id=cd.category_id AND cd.language_id='".(int)$this->config->get('config_language_id')."') WHERE 1";if(!empty($data['filter_name']))$sql.=" AND sd.name LIKE '%".$this->db->escape($data['filter_name'])."%'";if(isset($data['filter_category_id'])&&$data['filter_category_id']!=='')$sql.=" AND s.category_id='".(int)$data['filter_category_id']."'";if(isset($data['filter_status'])&&$data['filter_status']!=='')$sql.=" AND s.status='".(int)$data['filter_status']."'";$sort_data=array('sd.name','cd.name','s.price','s.sort_order','s.status','s.date_added');$sort=isset($data['sort'])&&in_array($data['sort'],$sort_data,true)?$data['sort']:'s.sort_order';$order=isset($data['order'])&&$data['order']==='DESC'?'DESC':'ASC';$sql.=" ORDER BY $sort $order, sd.name ASC";if(isset($data['start'])||isset($data['limit'])){$start=max(0,(int)($data['start']??0));$limit=max(1,(int)($data['limit']??20));$sql.=" LIMIT $start,$limit";}return $this->db->query($sql)->rows;}
    public function getTotalServices($data=array()){$sql="SELECT COUNT(*) AS total FROM ".DB_PREFIX."probg_service s LEFT JOIN ".DB_PREFIX."probg_service_description sd ON(s.service_id=sd.service_id AND sd.language_id='".(int)$this->config->get('config_language_id')."') WHERE 1";if(!empty($data['filter_name']))$sql.=" AND sd.name LIKE '%".$this->db->escape($data['filter_name'])."%'";if(isset($data['filter_category_id'])&&$data['filter_category_id']!=='')$sql.=" AND s.category_id='".(int)$data['filter_category_id']."'";if(isset($data['filter_status'])&&$data['filter_status']!=='')$sql.=" AND s.status='".(int)$data['filter_status']."'";return(int)$this->db->query($sql)->row['total'];}
    public function getServiceDescriptions($id){$d=array();foreach($this->db->query("SELECT * FROM ".DB_PREFIX."probg_service_description WHERE service_id='".(int)$id."'")->rows as $r)$d[$r['language_id']]=$r;return $d;}public function getServiceStores($id){return array_column($this->db->query("SELECT store_id FROM ".DB_PREFIX."probg_service_to_store WHERE service_id='".(int)$id."'")->rows,'store_id');}public function getServiceImages($id){return $this->db->query("SELECT * FROM ".DB_PREFIX."probg_service_image WHERE service_id='".(int)$id."' ORDER BY sort_order ASC,service_image_id ASC")->rows;}public function getServiceRelated($id){return array_column($this->db->query("SELECT related_id FROM ".DB_PREFIX."probg_service_related WHERE service_id='".(int)$id."'")->rows,'related_id');}public function getServiceProducts($id){return $this->db->query("SELECT product_id,sort_order FROM ".DB_PREFIX."probg_service_product WHERE service_id='".(int)$id."' ORDER BY sort_order ASC,product_id ASC")->rows;}public function getServiceSeoUrls($id){$d=array();foreach($this->db->query("SELECT store_id,language_id,keyword FROM ".DB_PREFIX."seo_url WHERE query='extension/probg_services/service&service_id=".(int)$id."'")->rows as $r)$d[$r['store_id']][$r['language_id']]=$r['keyword'];return $d;}public function getSeoUrlByKeyword($keyword,$store_id,$language_id){return $this->db->query("SELECT seo_url_id,query FROM ".DB_PREFIX."seo_url WHERE keyword='".$this->db->escape($keyword)."' AND store_id='".(int)$store_id."' AND language_id='".(int)$language_id."' LIMIT 1")->row;}
    private function saveDescriptions($id,$data){foreach($data['service_description'] as $language_id=>$v){$meta=trim($v['meta_title'])!==''?$v['meta_title']:$v['name'];$this->db->query("INSERT INTO ".DB_PREFIX."probg_service_description SET service_id='".(int)$id."',language_id='".(int)$language_id."',name='".$this->db->escape($v['name'])."',subtitle='".$this->db->escape($v['subtitle'])."',description_short='".$this->db->escape($v['description_short'])."',description='".$this->db->escape($v['description'])."',price_text='".$this->db->escape($v['price_text'])."',button_text='".$this->db->escape($v['button_text'])."',meta_title='".$this->db->escape($meta)."',meta_description='".$this->db->escape($v['meta_description'])."',meta_keyword='".$this->db->escape($v['meta_keyword'])."'");}}
    private function saveStores($id,$data){foreach(($data['service_store']??array(0)) as $store_id)$this->db->query("INSERT INTO ".DB_PREFIX."probg_service_to_store SET service_id='".(int)$id."',store_id='".(int)$store_id."'");}private function saveImages($id,$data){foreach(($data['service_image']??array()) as $img)if(!empty($img['image']))$this->db->query("INSERT INTO ".DB_PREFIX."probg_service_image SET service_id='".(int)$id."',image='".$this->db->escape($img['image'])."',sort_order='".(int)$img['sort_order']."'");}private function saveRelated($id,$data){foreach(($data['service_related']??array()) as $rid)if((int)$rid!==$id)$this->db->query("INSERT IGNORE INTO ".DB_PREFIX."probg_service_related SET service_id='".(int)$id."',related_id='".(int)$rid."'");}private function saveProducts($id,$data){foreach(($data['service_product']??array()) as $r){$pid=is_array($r)?(int)($r['product_id']??0):(int)$r;$sort=is_array($r)?(int)($r['sort_order']??0):0;if($pid)$this->db->query("INSERT IGNORE INTO ".DB_PREFIX."probg_service_product SET service_id='".(int)$id."',product_id='".$pid."',sort_order='".$sort."'");}}
    private function saveSeoUrls($id,$data){$stores=$data['service_store']??array(0);foreach($stores as $store_id)foreach($data['service_description'] as $language_id=>$d){$keyword=trim($data['service_seo_url'][$store_id][$language_id]??'');if($keyword==='')$keyword=$this->uniqueSlug($id.'-'.$this->slugify($d['name']),$store_id,$language_id,$id);if($keyword!=='')$this->db->query("INSERT INTO ".DB_PREFIX."seo_url SET store_id='".(int)$store_id."',language_id='".(int)$language_id."',query='extension/probg_services/service&service_id=".(int)$id."',keyword='".$this->db->escape($keyword)."'");}}private function deleteSeoUrls($id){$this->db->query("DELETE FROM ".DB_PREFIX."seo_url WHERE query='extension/probg_services/service&service_id=".(int)$id."'");}private function uniqueSlug($slug,$store_id,$language_id,$id){if($slug==='')$slug=$id.'-service';$base=$slug;$i=2;while(true){$r=$this->getSeoUrlByKeyword($slug,$store_id,$language_id);if(!$r||$r['query']==='extension/probg_services/service&service_id='.(int)$id)return $slug;$slug=$base.'-'.$i++;}}private function slugify($v){$m=array('а'=>'a','б'=>'b','в'=>'v','г'=>'g','д'=>'d','е'=>'e','ж'=>'zh','з'=>'z','и'=>'i','й'=>'y','к'=>'k','л'=>'l','м'=>'m','н'=>'n','о'=>'o','п'=>'p','р'=>'r','с'=>'s','т'=>'t','у'=>'u','ф'=>'f','х'=>'h','ц'=>'ts','ч'=>'ch','ш'=>'sh','щ'=>'sht','ъ'=>'a','ь'=>'','ю'=>'yu','я'=>'ya');$v=utf8_strtolower(trim($v));$v=strtr($v,$m);$v=preg_replace('/[^a-z0-9]+/u','-',$v);return trim($v,'-');}
}
